"""Private shared helpers for the warehouse cutover workspace.

Only the Python standard library is used. Nothing in this module hardcodes
component results; every parameter is taken from the caller or the contract.
"""

import json
import math
from pathlib import Path

CATEGORIES = ("prepare", "copy", "verify")
CATEGORY_INDEX = {"prepare": 0, "copy": 1, "verify": 2}


def is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def is_bool(value):
    return isinstance(value, bool)


def load_payload(path):
    """Read a UTF-8 JSON payload whose top level must be an object or array."""
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise ValueError("unable to read payload: %s" % path) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise ValueError("invalid JSON in payload: %s" % path) from exc
    if isinstance(data, (dict, list)):
        return data
    raise ValueError("payload top level must be an object or array: %s" % path)


def write_json(path, data):
    """Write JSON with the workspace-wide display format and a final newline."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(
        data,
        ensure_ascii=False,
        sort_keys=True,
        indent=2,
        allow_nan=False,
    ) + "\n"
    path.write_text(text, encoding="utf-8")


def normalize_id(value):
    if not isinstance(value, str):
        raise ValueError("id must be a non-empty string")
    value = value.strip()
    if not value:
        raise ValueError("id must be a non-empty string")
    return value


def normalize_lower(value, field):
    if not isinstance(value, str):
        raise ValueError("%s must be a non-empty string" % field)
    value = value.strip().lower()
    if not value:
        raise ValueError("%s must be a non-empty string" % field)
    return value


def normalize_tags(value):
    if not isinstance(value, list):
        raise ValueError("tags must be a list of non-empty strings")
    tags = []
    for item in value:
        if not isinstance(item, str):
            raise ValueError("tags must contain only non-empty strings")
        tag = item.strip().lower()
        if not tag:
            raise ValueError("tags must contain only non-empty strings")
        tags.append(tag)
    return sorted(set(tags))


def normalize_record(raw):
    """Validate and normalize one evidence record."""
    if not isinstance(raw, dict):
        raise ValueError("record must be an object")

    record_id = normalize_id(raw.get("id"))

    revision = raw.get("revision")
    if not is_int(revision) or revision < 0:
        raise ValueError("revision must be an integer >= 0")

    owner = normalize_lower(raw.get("owner"), "owner")
    category = normalize_lower(raw.get("category"), "category")
    if category not in CATEGORIES:
        raise ValueError("category must be prepare/copy/verify")

    tags = normalize_tags(raw.get("tags"))

    failures = raw.get("failures")
    if not is_int(failures) or failures < 0:
        raise ValueError("failures must be an integer >= 0")

    total = raw.get("total")
    if not is_int(total) or total < 1:
        raise ValueError("total must be an integer >= 1")

    lag = raw.get("lag")
    if not is_int(lag) or lag < 0:
        raise ValueError("lag must be an integer >= 0")

    valid = raw.get("valid")
    if not is_bool(valid):
        raise ValueError("valid must be a boolean")

    if failures > total:
        raise ValueError("failures must be <= total")

    return {
        "id": record_id,
        "revision": revision,
        "owner": owner,
        "category": category,
        "tags": tags,
        "failures": failures,
        "total": total,
        "lag": lag,
        "valid": valid,
    }


def latest_records(payload):
    """Validate every record, check same (id, revision) conflicts, pick latest revision."""
    if not isinstance(payload, list):
        raise ValueError("evidence input must be an array of records")

    normalized = [normalize_record(raw) for raw in payload]

    by_version = {}
    for record in normalized:
        key = (record["id"], record["revision"])
        if key in by_version:
            if by_version[key] != record:
                raise ValueError("conflicting records for id=%r revision=%r" % key)
        else:
            by_version[key] = record

    latest = {}
    for record in by_version.values():
        current = latest.get(record["id"])
        if current is None or record["revision"] > current["revision"]:
            latest[record["id"]] = record

    return list(latest.values())


def clamp_score(value):
    return max(0, min(20, value))


def failure_score(record, offset):
    return clamp_score(math.ceil(20 * record["failures"] / record["total"]) + offset)


def lag_score(record, sla, offset):
    return clamp_score(math.ceil(record["lag"] / sla) + offset)


def integrity_score(record, offset):
    base = 0 if record["valid"] else 15
    return clamp_score(base + record["failures"] + offset)


def unwrap_records(payload):
    """Read result.records from an upstream component wrapper."""
    if not isinstance(payload, dict) or set(payload.keys()) != {"name", "result"}:
        raise ValueError("input must be a component wrapper with name/result keys")
    result = payload.get("result")
    if not isinstance(result, dict):
        raise ValueError("component wrapper result must be an object")
    records = result.get("records")
    if not isinstance(records, list):
        raise ValueError("component wrapper result.records must be a list")
    return records


def merge_records(payloads):
    """Merge result.records across wrappers, dedup by (source, id)."""
    merged = {}
    for payload in payloads:
        for record in unwrap_records(payload):
            if not isinstance(record, dict):
                raise ValueError("record must be an object")
            key = (record["source"], record["id"])
            if key in merged:
                if merged[key] != record:
                    raise ValueError("source/id conflict: %s:%s" % key)
            else:
                merged[key] = record
    return list(merged.values())


def build_component(root, contract_path, transform):
    """Read a contract and its inputs, run transform, write contract output."""
    root = Path(root)
    contract_path = Path(contract_path)
    contract = json.loads(contract_path.read_text(encoding="utf-8"))
    payloads = [load_payload(root / input_path) for input_path in contract["inputs"]]
    result = transform(payloads, contract)
    write_json(root / contract["output"], result)
    return result

