from _shared import CATEGORY_INDEX, merge_records  # noqa: E402


def _empty_result(name):
    return {
        "name": name,
        "result": {
            "records": [],
            "blocked": False,
            "waves": [],
            "critical_path": [],
            "makespan": 0,
            "earliest_finish": {},
        },
    }


def transform(payloads, contract):
    merged = merge_records(payloads)
    name = contract["name"]
    threshold = contract["threshold"]
    only_if_blocking = contract["only_if_blocking"]

    kept = merged
    if only_if_blocking:
        blocking = any(
            "blocking" in r["tags"] and r["score"] >= threshold for r in merged
        )
        if not blocking:
            kept = []

    records = sorted(kept, key=lambda r: (r["source"], r["id"]))
    if not kept:
        result = _empty_result(name)["result"]
        result["records"] = records
        return {"name": name, "result": result}

    nodes = {}
    for record in kept:
        full_id = "%s:%s" % (record["source"], record["id"])
        nodes[full_id] = {
            "id": full_id,
            "duration": 1 + record["score"] // 5,
            "category": record["category"],
        }

    predecessors = {}
    for node_id, node in nodes.items():
        index = CATEGORY_INDEX[node["category"]]
        predecessors[node_id] = {
            other_id
            for other_id, other in nodes.items()
            if CATEGORY_INDEX[other["category"]] < index
        }

    waves = []
    committed = set()
    remaining = set(nodes.keys())
    while remaining:
        ready = {node_id for node_id in remaining if predecessors[node_id] <= committed}
        if not ready:
            raise ValueError("cycle detected in remediation dependency graph")
        wave = sorted(ready)
        waves.append(wave)
        committed.update(ready)
        remaining -= ready

    finish = {}
    paths = {}
    for wave in waves:
        for node_id in wave:
            preds = sorted(predecessors[node_id])
            if not preds:
                finish[node_id] = nodes[node_id]["duration"]
                paths[node_id] = [node_id]
                continue
            max_finish = max(finish[p] for p in preds)
            best = min(
                (p for p in preds if finish[p] == max_finish),
                key=lambda p: paths[p],
            )
            finish[node_id] = nodes[node_id]["duration"] + max_finish
            paths[node_id] = paths[best] + [node_id]

    all_ids = sorted(nodes.keys())
    max_finish = max(finish[node_id] for node_id in all_ids)
    endpoint = min(
        (node_id for node_id in all_ids if finish[node_id] == max_finish),
        key=lambda node_id: paths[node_id],
    )

    earliest_finish = {node_id: finish[node_id] for node_id in all_ids}

    return {
        "name": name,
        "result": {
            "records": records,
            "blocked": False,
            "waves": waves,
            "critical_path": paths[endpoint],
            "makespan": finish[endpoint],
            "earliest_finish": earliest_finish,
        },
    }

